import React, { useEffect, useRef, useState } from 'react';
import {
  Animated,
  Platform,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { createPortal } from 'react-dom';
import { LinearGradient } from 'expo-linear-gradient';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';

import SplashLogoScreen from '../screens/SplashLogoScreen';
import TelaInicio from '../screens/Inicio';
import TelaCriarEscala from '../screens/TelaCriarEscala';
import TelaListaEscalas from '../screens/TelaListaEscalas';
import TelaDetalhesEscala from '../screens/DetalhesEscala';
import RepertoiresScreen from '../screens/Repertorios';
import AdicionarRepertorio from '../screens/AdicionarRepertorio';
import DetalheRepertorio from '../screens/DetalheRepertorio';
import VisualizarArquivo from '../screens/VisualizarArquivo';
import PresencaScreen from '../screens/Presenca';
import InteracaoScreen from '../screens/Interacao';
import AvisosScreen from '../screens/Avisos';
import EnsaiosScreen from '../screens/Ensaios';
import TelaAniversariantes from '../screens/Aniversariantes';
import TelaAgenda from '../screens/Agenda';

const Stack = createStackNavigator();

// React Native usa "absolute". No PWA, "fixed" mantém a navbar presa à janela
// mesmo quando a tela interna possui rolagem vertical.
const POSICAO_FIXA_WEB = Platform.OS === 'web'
  ? ({ position: 'fixed' } as any)
  : null;

type ItemNavbar = {
  rota: string;
  titulo: string;
  icone: string;
};

const ITENS_NAVBAR: ItemNavbar[] = [
  { rota: 'Avisos', titulo: 'Avisos', icone: 'bell-ring-outline' },
  { rota: 'Repertorios', titulo: 'Repertórios', icone: 'music-box-multiple-outline' },
  { rota: 'Escalas', titulo: 'Escalas', icone: 'calendar-month-outline' },
  { rota: 'CriarEscala', titulo: 'Criar escala', icone: 'plus' },
  { rota: 'Inicio', titulo: 'Início', icone: 'home' },
  { rota: 'Presenca', titulo: 'Presença', icone: 'account-check-outline' },
  { rota: 'Ensaios', titulo: 'Devocional', icone: 'book-open-page-variant-outline' },
  { rota: 'Aniversariantes', titulo: 'Aniversariantes', icone: 'gift-outline' },
  { rota: 'Agenda', titulo: 'Agenda', icone: 'calendar-text-outline' },
];

function obterRotaAtiva(rotaAtual: string) {
  if (
    rotaAtual === 'AdicionarRepertorio' ||
    rotaAtual === 'DetalheRepertorio' ||
    rotaAtual === 'VisualizarArquivo'
  ) {
    return 'Repertorios';
  }

  if (rotaAtual === 'DetalhesEscala') {
    return 'Escalas';
  }

  return rotaAtual;
}

function BotaoNavbar({
  item,
  selecionado,
  onPress,
}: {
  item: ItemNavbar;
  selecionado: boolean;
  onPress: () => void;
}) {
  const animacao = useRef(new Animated.Value(selecionado ? 1 : 0)).current;

  useEffect(() => {
    Animated.spring(animacao, {
      toValue: selecionado ? 1 : 0,
      friction: 7,
      tension: 85,
      useNativeDriver: true,
    }).start();
  }, [animacao, selecionado]);

  const translateY = animacao.interpolate({
    inputRange: [0, 1],
    outputRange: [0, -2],
  });

  const scale = animacao.interpolate({
    inputRange: [0, 1],
    outputRange: [1, 1.1],
  });

  return (
    <TouchableOpacity
      style={[
        estilos.itemNavbar,
        selecionado && estilos.itemNavbarSelecionado,
      ]}
      onPress={onPress}
      activeOpacity={0.8}
      accessibilityLabel={item.titulo}
    >
      <Animated.View
        style={[
          estilos.circuloIcone,
          selecionado ? estilos.circuloSelecionado : estilos.circuloNormal,
          { transform: [{ translateY }, { scale }] },
        ]}
      >
        {selecionado && <View style={estilos.haloSelecionado} />}
        <MaterialCommunityIcons
          name={item.icone}
          size={selecionado ? 22 : 19}
          color={selecionado ? '#071426' : '#E5EDF8'}
        />
      </Animated.View>
    </TouchableOpacity>
  );
}

function BarraNavegacaoFixa({
  rotaAtual,
  onNavigate,
}: {
  rotaAtual: string;
  onNavigate: (rota: string) => void;
}) {
  if (!rotaAtual || rotaAtual === 'SplashLogo') return null;

  const rotaAtiva = obterRotaAtiva(rotaAtual);

  const navbar = (
    <View
      style={[estilos.areaNavbar, POSICAO_FIXA_WEB]}
      pointerEvents="box-none"
    >
      <LinearGradient
        colors={['#122339', '#081322', '#050D19']}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={estilos.navbar}
      >
        <View style={estilos.luzSuperior} />
        <View style={estilos.listaNavbar}>
          {ITENS_NAVBAR.map(item => (
            <BotaoNavbar
              key={item.rota}
              item={item}
              selecionado={item.rota === rotaAtiva}
              onPress={() => onNavigate(item.rota)}
            />
          ))}
        </View>
      </LinearGradient>
    </View>
  );

  // O React Navigation aplica transformações CSS às telas. Um elemento fixed
  // dentro de um ancestral transformado acompanha a rolagem desse ancestral.
  // No PWA, o portal move somente a navbar para o body, tornando-a realmente
  // fixa em relação à janela do navegador.
  if (Platform.OS === 'web' && typeof document !== 'undefined') {
    return createPortal(navbar, document.body);
  }

  return navbar;
}

export default function AppNavigator(): JSX.Element {
  const [rotaAtual, setRotaAtual] = useState('SplashLogo');
  const navegacaoStack = useRef<any>(null);

  function navegarPelaNavbar(rota: string) {
    if (rota === rotaAtual) return;
    navegacaoStack.current?.navigate(rota);
  }

  return (
    <View style={estilos.containerPrincipal}>
      <View style={estilos.areaConteudo}>
        <Stack.Navigator
          initialRouteName="SplashLogo"
          screenOptions={{
            headerShown: false,
            cardStyle: { backgroundColor: '#071426' },
          }}
          screenListeners={({ navigation, route }) => ({
            focus: () => {
              navegacaoStack.current = navigation;
              setRotaAtual(route.name);
            },
          })}
        >
          <Stack.Screen name="SplashLogo" component={SplashLogoScreen} />
          <Stack.Screen name="Inicio" component={TelaInicio} />
          <Stack.Screen name="CriarEscala" component={TelaCriarEscala} />
          <Stack.Screen name="Escalas" component={TelaListaEscalas} />
          <Stack.Screen name="DetalhesEscala" component={TelaDetalhesEscala} />
          <Stack.Screen name="Repertorios" component={RepertoiresScreen} />
          <Stack.Screen name="AdicionarRepertorio" component={AdicionarRepertorio} />
          <Stack.Screen name="DetalheRepertorio" component={DetalheRepertorio} />
          <Stack.Screen name="VisualizarArquivo" component={VisualizarArquivo} />
          <Stack.Screen name="Presenca" component={PresencaScreen} />
          <Stack.Screen name="Interacao" component={InteracaoScreen} />
          <Stack.Screen name="Avisos" component={AvisosScreen} />
          <Stack.Screen name="Ensaios" component={EnsaiosScreen} />
          <Stack.Screen name="Aniversariantes" component={TelaAniversariantes} />
          <Stack.Screen name="Agenda" component={TelaAgenda} />
        </Stack.Navigator>
      </View>

      <BarraNavegacaoFixa
        rotaAtual={rotaAtual}
        onNavigate={navegarPelaNavbar}
      />
    </View>
  );
}

