import React, { useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  KeyboardAvoidingView,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from 'react-native';
import {
  addDoc,
  collection,
  deleteDoc,
  doc,
  getDocs,
  getFirestore,
  orderBy,
  query,
  Timestamp,
  updateDoc,
} from 'firebase/firestore';
import { MaterialCommunityIcons, MaterialIcons } from '@expo/vector-icons';
import { getAuth } from 'firebase/auth';
import { useNavigation } from '@react-navigation/native';
import { LinearGradient } from 'expo-linear-gradient';

const db = getFirestore();

const IUDS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

type Agendamento = {
  id?: string;
  titulo: string;
  data: string;
  descricao?: string;
  criadoEm?: any;
};

function formatarDataInput(texto: string): string {
  const numeros = texto.replace(/\D/g, '').slice(0, 8);
  if (numeros.length > 4) {
    return numeros.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  }
  if (numeros.length > 2) {
    return numeros.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  }
  return numeros;
}

function separarData(data: string) {
  const [dia = '--', mes = '--', ano = '----'] = data.split('/');
  return { dia, mes, ano };
}

export default function TelaAgenda(): JSX.Element {
  const navigation = useNavigation<any>();
  const [agendamentos, setAgendamentos] = useState<Agendamento[]>([]);
  const [novoTitulo, setNovoTitulo] = useState('');
  const [novaData, setNovaData] = useState('');
  const [novaDescricao, setNovaDescricao] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [salvando, setSalvando] = useState(false);

  const podeAdministrar = Boolean(uidAtual && IUDS.includes(uidAtual));

  useEffect(() => {
    setUidAtual(getAuth().currentUser?.uid ?? null);
    buscarAgendamentos();
  }, []);

  async function buscarAgendamentos() {
    setCarregando(true);
    try {
      const consulta = query(collection(db, 'agendas'), orderBy('data'));
      const snapshot = await getDocs(consulta);
      const lista: Agendamento[] = [];
      snapshot.forEach(documento => {
        lista.push({ id: documento.id, ...documento.data() } as Agendamento);
      });
      setAgendamentos(lista);
    } catch {
      Alert.alert('Erro', 'Não foi possível carregar os agendamentos.');
    } finally {
      setCarregando(false);
    }
  }

  function limparFormulario() {
    setNovoTitulo('');
    setNovaData('');
    setNovaDescricao('');
    setEditandoId(null);
  }

  function abrirNovoAgendamento() {
    limparFormulario();
    setModalVisible(true);
  }

  function abrirEdicao(agendamento: Agendamento) {
    if (!agendamento.id || !podeAdministrar) return;
    setEditandoId(agendamento.id);
    setNovoTitulo(agendamento.titulo || '');
    setNovaData(agendamento.data || '');
    setNovaDescricao(agendamento.descricao || '');
    setModalVisible(true);
  }

  function fecharModal() {
    setModalVisible(false);
    limparFormulario();
  }

  async function salvarAgendamento() {
    const tituloFormatado = novoTitulo.trim();
    const dataFormatada = novaData.trim();

    if (!tituloFormatado || !dataFormatada.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
      Alert.alert('Dados incompletos', 'Preencha corretamente o título e a data (dd/mm/aaaa).');
      return;
    }

    setSalvando(true);
    try {
      if (editandoId) {
        await updateDoc(doc(db, 'agendas', editandoId), {
          titulo: tituloFormatado,
          data: dataFormatada,
          descricao: novaDescricao.trim(),
        });
      } else {
        await addDoc(collection(db, 'agendas'), {
          titulo: tituloFormatado,
          data: dataFormatada,
          descricao: novaDescricao.trim(),
          criadoEm: Timestamp.now(),
        });
      }

      fecharModal();
      await buscarAgendamentos();
    } catch {
      Alert.alert(
        'Erro',
        editandoId
          ? 'Não foi possível atualizar o agendamento.'
          : 'Não foi possível adicionar o agendamento.',
      );
    } finally {
      setSalvando(false);
    }
  }

  const excluirAgendamento = async (id: string | undefined) => {
    if (!id || !uidAtual || !IUDS.includes(uidAtual)) return;
    try {
      await getAuth().currentUser?.getIdToken(true);
      await deleteDoc(doc(db, 'agendas', id));
      setAgendamentos(lista => lista.filter(agendamento => agendamento.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir agendamento:', error);
    }
  };

  return (
    <LinearGradient
      colors={['#071426', '#0B1A31', '#071426']}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
      style={styles.screen}
    >
      <View style={styles.topGlow} />
      <KeyboardAvoidingView
        style={styles.keyboardAvoiding}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={styles.header}>
            <TouchableOpacity style={styles.headerButton} onPress={() => navigation.navigate('Inicio')}>
              <MaterialIcons name="home" size={21} color="#DCE6F8" />
            </TouchableOpacity>
            <View style={styles.headerCenter}>
              <Text style={styles.headerEyebrow}>ORGANIZAÇÃO</Text>
              <Text style={styles.headerTitle}>Agenda</Text>
            </View>
            <TouchableOpacity style={styles.headerButton} onPress={() => navigation.goBack()}>
              <MaterialIcons
  name="arrow-back"
  size={22}
  color="#DCE6F8"
/>
            </TouchableOpacity>
          </View>

          <View style={styles.heroCard}>
            <View style={styles.heroIcon}>
              <MaterialCommunityIcons name="calendar-star" size={29} color="#40E0D0" />
            </View>
            <View style={styles.heroContent}>
              <Text style={styles.heroEyebrow}>AGENDA DA EQUIPE</Text>
              <Text style={styles.heroTitle}>Próximos compromissos</Text>
              <Text style={styles.heroText}>Reuniões, ensaios e eventos importantes.</Text>
            </View>
            <View style={styles.counterBadge}>
              <Text style={styles.counterNumber}>{agendamentos.length}</Text>
              <Text style={styles.counterLabel}>{agendamentos.length === 1 ? 'EVENTO' : 'EVENTOS'}</Text>
            </View>
          </View>

          {podeAdministrar && (
            <TouchableOpacity
              style={styles.newButton}
              onPress={abrirNovoAgendamento}
              activeOpacity={0.84}
            >
              <View style={styles.newButtonIcon}>
                <MaterialIcons name="add" size={21} color="#071426" />
              </View>
              <Text style={styles.newButtonText}>Novo agendamento</Text>
              <MaterialIcons name="arrow-forward-ios" size={16} color="#071426" />
            </TouchableOpacity>
          )}

          <View style={styles.listHeader}>
            <View>
              <Text style={styles.sectionEyebrow}>PROGRAMAÇÃO</Text>
              <Text style={styles.listTitle}>Compromissos cadastrados</Text>
            </View>
            <MaterialIcons name="event-note" size={22} color="#6E809D" />
          </View>

          {carregando ? (
            <View style={styles.loadingArea}>
              <ActivityIndicator size="large" color="#40E0D0" />
              <Text style={styles.loadingText}>Carregando agenda...</Text>
            </View>
          ) : agendamentos.length === 0 ? (
            <View style={styles.emptyCard}>
              <View style={styles.emptyIcon}>
                <MaterialCommunityIcons name="calendar-remove" size={31} color="#71819D" />
              </View>
              <Text style={styles.emptyTitle}>Nenhum compromisso cadastrado</Text>
              <Text style={styles.emptyText}>Os próximos eventos da equipe aparecerão aqui.</Text>
            </View>
          ) : (
            agendamentos.map((item, indice) => {
              const dataSeparada = separarData(item.data);
              return (
                <View key={item.id || `${item.titulo}-${item.data}-${indice}`} style={styles.eventCard}>
                  <View style={styles.cardGlow} />
                  <View style={styles.dateBadge}>
                    <Text style={styles.dateDay}>{dataSeparada.dia}</Text>
                    <Text style={styles.dateMonth}>/{dataSeparada.mes}</Text>
                    <Text style={styles.dateYear}>{dataSeparada.ano}</Text>
                  </View>

                  <View style={styles.eventContent}>
                    <Text style={styles.eventEyebrow}>COMPROMISSO</Text>
                    <Text style={styles.eventTitle}>{item.titulo}</Text>
                    <View style={styles.fullDateRow}>
                      <MaterialIcons name="calendar-today" size={14} color="#40E0D0" />
                      <Text style={styles.fullDateText}>{item.data}</Text>
                    </View>
                  </View>

                  {podeAdministrar && (
                    <View style={styles.cardActions}>
                      <TouchableOpacity
                        style={[styles.iconButton, styles.editIconButton]}
                        onPress={() => abrirEdicao(item)}
                        activeOpacity={0.78}
                      >
                        <MaterialIcons name="edit" size={19} color="#FFC857" />
                      </TouchableOpacity>
                      <TouchableOpacity
                        style={[styles.iconButton, styles.deleteIconButton]}
                        onPress={() => excluirAgendamento(item.id)}
                        activeOpacity={0.78}
                      >
                        <MaterialIcons name="delete-outline" size={20} color="#FF617B" />
                      </TouchableOpacity>
                    </View>
                  )}

                  {!!item.descricao?.trim() && (
                    <View style={styles.descriptionBox}>
                      <View style={styles.descriptionIcon}>
                        <MaterialIcons name="notes" size={17} color="#FFC857" />
                      </View>
                      <Text style={styles.descriptionText}>{item.descricao}</Text>
                    </View>
                  )}
                </View>
              );
            })
          )}
        </ScrollView>

        <Modal
          visible={modalVisible}
          animationType="fade"
          transparent
          onRequestClose={fecharModal}
        >
          <KeyboardAvoidingView
            style={styles.modalOverlay}
            behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          >
            <View style={styles.modalBox}>
              <View style={styles.modalHeader}>
                <View style={styles.modalIcon}>
                  <MaterialIcons
                    name={editandoId ? 'edit' : 'event'}
                    size={23}
                    color="#40E0D0"
                  />
                </View>
                <View style={styles.modalTitleArea}>
                  <Text style={styles.modalEyebrow}>{editandoId ? 'ATUALIZAR EVENTO' : 'NOVO EVENTO'}</Text>
                  <Text style={styles.modalTitle}>
                    {editandoId ? 'Editar agendamento' : 'Novo agendamento'}
                  </Text>
                </View>
                <TouchableOpacity style={styles.modalCloseButton} onPress={fecharModal} disabled={salvando}>
                  <MaterialIcons name="close" size={20} color="#91A0BA" />
                </TouchableOpacity>
              </View>

              <Text style={styles.fieldLabel}>Título</Text>
              <View style={styles.inputWrapper}>
                <MaterialIcons name="title" size={19} color="#7D8EAA" />
                <TextInput
                  style={styles.input}
                  placeholder="Ex.: Reunião do ministério"
                  value={novoTitulo}
                  onChangeText={setNovoTitulo}
                  placeholderTextColor="#64738F"
                />
              </View>

              <Text style={styles.fieldLabel}>Data</Text>
              <View style={styles.inputWrapper}>
                <MaterialIcons name="calendar-today" size={18} color="#7D8EAA" />
                <TextInput
                  style={styles.input}
                  placeholder="DD/MM/AAAA"
                  value={novaData}
                  onChangeText={texto => setNovaData(formatarDataInput(texto))}
                  placeholderTextColor="#64738F"
                  keyboardType="numeric"
                  maxLength={10}
                />
              </View>

              <Text style={styles.fieldLabel}>Descrição <Text style={styles.optional}>(opcional)</Text></Text>
              <View style={[styles.inputWrapper, styles.textAreaWrapper]}>
                <MaterialIcons name="notes" size={19} color="#7D8EAA" style={styles.textAreaIcon} />
                <TextInput
                  style={[styles.input, styles.textAreaInput]}
                  placeholder="Informações sobre o compromisso"
                  value={novaDescricao}
                  onChangeText={setNovaDescricao}
                  placeholderTextColor="#64738F"
                  multiline
                  textAlignVertical="top"
                />
              </View>

              <View style={styles.modalActions}>
                <TouchableOpacity
                  style={styles.cancelButton}
                  onPress={fecharModal}
                  disabled={salvando}
                >
                  <Text style={styles.cancelButtonText}>Cancelar</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[styles.saveButton, salvando && styles.buttonDisabled]}
                  onPress={salvarAgendamento}
                  disabled={salvando}
                  activeOpacity={0.84}
                >
                  {salvando ? (
                    <ActivityIndicator color="#071426" />
                  ) : (
                    <>
                      <MaterialIcons name="save-alt" size={20} color="#071426" />
                      <Text style={styles.saveButtonText}>
                        {editandoId ? 'Salvar alterações' : 'Criar agendamento'}
                      </Text>
                    </>
                  )}
                </TouchableOpacity>
              </View>
            </View>
          </KeyboardAvoidingView>
        </Modal>
      </KeyboardAvoidingView>
    </LinearGradient>
  );
}

