import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Animated,
  KeyboardAvoidingView,
  Linking,
  Modal,
  Platform,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import { addDoc, collection, getFirestore, onSnapshot } from 'firebase/firestore';
import { useNavigation } from '@react-navigation/native';
import { MaterialIcons } from '@expo/vector-icons';

const db = getFirestore();
const COLECAO_REPERTORIOS = 'repertorios';

function normalizarTexto(valor: string): string {
  return valor
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLocaleLowerCase('pt-BR');
}

const MESES = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro',
];
const DIAS_SEMANA = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

const tonsMaiores = [
  'C',
  'C#',
  'D',
  'D#',
  'E',
  'F',
  'F#',
  'G',
  'G#',
  'A',
  'A#',
  'B',
];

const tonsMenores = [
  'Cm',
  'C#m',
  'Dm',
  'D#m',
  'Em',
  'Fm',
  'F#m',
  'Gm',
  'G#m',
  'Am',
  'A#m',
  'Bm',
];

export interface Musica {
  nome: string;
  tom: string;
  linkLetra?: string;
  linkYoutube?: string;
  linkCifra?: string;
  observacoes?: string;
}

interface MusicaBanco extends Musica {
  id: string;
}

export default function AdicionarRepertorio(): JSX.Element {
  const navigation = useNavigation<any>();
  const { width } = useWindowDimensions();
  const layoutMobile = width < 520;

  const [titulo, setTitulo] = useState('');
  const [data, setData] = useState('');
  const [responsavel, setResponsavel] = useState('');

  const [musicas, setMusicas] = useState<Musica[]>([]);
  const [musicaNome, setMusicaNome] = useState('');
  const [musicaTom, setMusicaTom] = useState('C');
  const [musicaLinkLetra, setMusicaLinkLetra] = useState('');
  const [musicaLinkYoutube, setMusicaLinkYoutube] = useState('');
  const [musicaLinkCifra, setMusicaLinkCifra] = useState('');
  const [musicaObservacoes, setMusicaObservacoes] = useState('');
  const [catalogoMusicas, setCatalogoMusicas] = useState<MusicaBanco[]>([]);
  const [mostrarSugestoes, setMostrarSugestoes] = useState(false);
  const [carregandoCatalogo, setCarregandoCatalogo] = useState(true);

  const [calendarioVisivel, setCalendarioVisivel] = useState(false);
  const [mesCalendario, setMesCalendario] = useState(new Date());

  const [loading, setLoading] = useState(false);
  const saveAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    const unsubscribe = onSnapshot(
      collection(db, COLECAO_REPERTORIOS),
      snapshot => {
        const repertoriosOrdenados = snapshot.docs
          .map(documento => {
            const dados = documento.data() as Record<string, any>;
            const criadoEm = dados.criadoEm;
            const ordem = typeof criadoEm?.toMillis === 'function'
              ? criadoEm.toMillis()
              : new Date(dados.data || 0).getTime() || 0;

            return { id: documento.id, dados, ordem };
          })
          .sort((a, b) => b.ordem - a.ordem);

        const musicasUnicas = new Map<string, MusicaBanco>();

        repertoriosOrdenados.forEach(repertorio => {
          const listaMusicas = Array.isArray(repertorio.dados.musicas)
            ? repertorio.dados.musicas
            : [];

          listaMusicas.forEach((valor: Record<string, any>, indice: number) => {
            const nome = String(valor?.nome || valor?.titulo || valor?.musica || '').trim();
            if (!nome) return;

            const chave = normalizarTexto(nome);
            const musicaEncontrada: MusicaBanco = {
              id: `${repertorio.id}-${indice}`,
              nome,
              tom: String(valor?.tom || valor?.tonalidade || 'C').trim() || 'C',
              linkLetra: String(valor?.linkLetra || valor?.letra || valor?.link_letra || '').trim(),
              linkYoutube: String(valor?.linkYoutube || valor?.youtube || valor?.link_youtube || '').trim(),
              linkCifra: String(valor?.linkCifra || valor?.cifra || valor?.link_cifra || '').trim(),
              observacoes: String(valor?.observacoes || valor?.observacao || valor?.obs || '').trim(),
            };

            const existente = musicasUnicas.get(chave);
            if (!existente) {
              musicasUnicas.set(chave, musicaEncontrada);
              return;
            }

            // Mantém os dados do repertório mais recente e completa campos vazios
            // com informações encontradas em repertórios anteriores.
            musicasUnicas.set(chave, {
              ...existente,
              tom: existente.tom || musicaEncontrada.tom,
              linkLetra: existente.linkLetra || musicaEncontrada.linkLetra,
              linkYoutube: existente.linkYoutube || musicaEncontrada.linkYoutube,
              linkCifra: existente.linkCifra || musicaEncontrada.linkCifra,
              observacoes: existente.observacoes || musicaEncontrada.observacoes,
            });
          });
        });

        const catalogo = Array.from(musicasUnicas.values())
          .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));

        setCatalogoMusicas(catalogo);
        setCarregandoCatalogo(false);
      },
      error => {
        console.log('Erro ao carregar músicas dos repertórios:', error);
        setCarregandoCatalogo(false);
      },
    );

    return () => unsubscribe();
  }, []);

  const sugestoesMusicas = useMemo(() => {
    const termo = normalizarTexto(musicaNome);
    if (!termo) return catalogoMusicas.slice(0, 6);

    return catalogoMusicas
      .filter(musica => normalizarTexto(musica.nome).includes(termo))
      .slice(0, 6);
  }, [catalogoMusicas, musicaNome]);

  const diasDoCalendario = useMemo(() => {
    const ano = mesCalendario.getFullYear();
    const mes = mesCalendario.getMonth();
    const primeiroDia = new Date(ano, mes, 1).getDay();
    const quantidadeDias = new Date(ano, mes + 1, 0).getDate();
    const celulas: Array<number | null> = Array(primeiroDia).fill(null);

    for (let dia = 1; dia <= quantidadeDias; dia += 1) celulas.push(dia);
    while (celulas.length % 7 !== 0) celulas.push(null);
    return celulas;
  }, [mesCalendario]);

  function formatarData(dataSelecionada: Date) {
    const dia = String(dataSelecionada.getDate()).padStart(2, '0');
    const mes = String(dataSelecionada.getMonth() + 1).padStart(2, '0');
    return `${dia}/${mes}/${dataSelecionada.getFullYear()}`;
  }

  function abrirCalendario() {
    const partes = data.split('/').map(Number);
    if (partes.length === 3 && partes.every(Number.isFinite)) {
      const [dia, mes, ano] = partes;
      const dataAtual = new Date(ano, mes - 1, dia);
      if (!Number.isNaN(dataAtual.getTime())) setMesCalendario(dataAtual);
    }
    setCalendarioVisivel(true);
  }

  function mudarMes(direcao: number) {
    setMesCalendario(atual => new Date(atual.getFullYear(), atual.getMonth() + direcao, 1));
  }

  function selecionarDia(dia: number) {
    const selecionada = new Date(
      mesCalendario.getFullYear(),
      mesCalendario.getMonth(),
      dia,
    );
    setData(formatarData(selecionada));
    setCalendarioVisivel(false);
  }

  function diaEstaSelecionado(dia: number) {
    return data === formatarData(
      new Date(mesCalendario.getFullYear(), mesCalendario.getMonth(), dia),
    );
  }

  function diaEhHoje(dia: number) {
    const hoje = new Date();
    return dia === hoje.getDate()
      && mesCalendario.getMonth() === hoje.getMonth()
      && mesCalendario.getFullYear() === hoje.getFullYear();
  }

  function selecionarMusicaDoBanco(musica: MusicaBanco) {
    setMusicaNome(musica.nome);
    setMusicaTom(musica.tom || 'C');
    setMusicaLinkLetra(musica.linkLetra || '');
    setMusicaLinkYoutube(musica.linkYoutube || '');
    setMusicaLinkCifra(musica.linkCifra || '');
    setMusicaObservacoes(musica.observacoes || '');
    setMostrarSugestoes(false);
  }

  function limparFormularioMusica() {
    setMusicaNome('');
    setMusicaTom('C');
    setMusicaLinkLetra('');
    setMusicaLinkYoutube('');
    setMusicaLinkCifra('');
    setMusicaObservacoes('');
    setMostrarSugestoes(false);
  }

  function handleAdicionarMusica() {
    const nomeFormatado = musicaNome.trim();

    if (!nomeFormatado) {
      Alert.alert('Atenção', 'Informe o nome da música antes de adicionar.');
      return;
    }

    const musicaJaAdicionada = musicas.some(
      musica => musica.nome.toLowerCase() === nomeFormatado.toLowerCase(),
    );

    if (musicaJaAdicionada) {
      Alert.alert('Música já adicionada', 'Essa música já está no repertório.');
      return;
    }

    setMusicas(listaAtual => [
      ...listaAtual,
      {
        nome: nomeFormatado,
        tom: musicaTom,
        linkLetra: musicaLinkLetra.trim(),
        linkYoutube: musicaLinkYoutube.trim(),
        linkCifra: musicaLinkCifra.trim(),
        observacoes: musicaObservacoes.trim(),
      },
    ]);

    limparFormularioMusica();
  }

  function removerMusica(indice: number) {
    Alert.alert(
      'Remover música',
      'Deseja remover esta música do repertório?',
      [
        { text: 'Cancelar', style: 'cancel' },
        {
          text: 'Remover',
          style: 'destructive',
          onPress: () => {
            setMusicas(listaAtual =>
              listaAtual.filter((_, index) => index !== indice),
            );
          },
        },
      ],
    );
  }

  async function abrirLink(link?: string, tipo?: string) {
    if (!link) {
      Alert.alert(
        'Link não informado',
        `Nenhum link de ${tipo || 'conteúdo'} foi adicionado para esta música.`,
      );
      return;
    }

    try {
      const podeAbrir = await Linking.canOpenURL(link);

      if (!podeAbrir) {
        Alert.alert('Link inválido', 'Não foi possível abrir este link.');
        return;
      }

      await Linking.openURL(link);
    } catch {
      Alert.alert('Erro', 'Não foi possível abrir o link informado.');
    }
  }

  async function salvarRepertorio() {
    if (!titulo.trim() || !data.trim() || !responsavel.trim()) {
      Alert.alert(
        'Campos obrigatórios',
        'Preencha título, data e responsável.',
      );
      return;
    }

    if (musicas.length === 0) {
      Alert.alert(
        'Adicione músicas',
        'Inclua pelo menos uma música no repertório.',
      );
      return;
    }

    setLoading(true);

    try {
      await addDoc(collection(db, 'repertorios'), {
        titulo: titulo.trim(),
        data,
        responsavel: responsavel.trim(),
        musicas,
        criadoEm: new Date(),
      });

      Alert.alert('Sucesso', 'Repertório criado com sucesso!', [
        {
          text: 'OK',
          onPress: () => navigation.goBack(),
        },
      ]);
    } catch {
      Alert.alert(
        'Erro ao salvar',
        'Não foi possível salvar o repertório. Verifique sua conexão e tente novamente.',
      );
    } finally {
      setLoading(false);
    }
  }

  function handlePressIn() {
    Animated.spring(saveAnim, {
      toValue: 0.97,
      useNativeDriver: true,
    }).start();
  }

  function handlePressOut() {
    Animated.spring(saveAnim, {
      toValue: 1,
      friction: 4,
      tension: 50,
      useNativeDriver: true,
    }).start();
  }

  function renderTom(tom: string) {
    const tomMenor = tom.includes('m');

    return (
      <View style={styles.tomBox}>
        <Text style={styles.tomLabel}>Tom</Text>
        <Text style={styles.tomValue}>{tom}</Text>
        <Text style={styles.tomType}>
          {tomMenor ? 'MENOR' : 'MAIOR'}
        </Text>
      </View>
    );
  }

  return (
    <View style={styles.screen}>
      <KeyboardAvoidingView
        style={styles.keyboardAvoiding}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <ScrollView
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={styles.topGlow} />

          <View style={styles.header}>
            <TouchableOpacity
              style={styles.headerButton}
              onPress={() => navigation.navigate('Inicio')}
              activeOpacity={0.8}
            >
              <MaterialIcons name="home-filled" size={22} color="#FFFFFF" />
            </TouchableOpacity>

            <View style={styles.headerCenter}>
              <Text style={styles.headerEyebrow}>MINISTÉRIO DE LOUVOR</Text>
              <Text style={styles.headerTitle}>Novo Repertório</Text>
            </View>

            <TouchableOpacity
              style={styles.headerButton}
              onPress={() => navigation.goBack()}
              activeOpacity={0.8}
            >
              <MaterialIcons name="arrow-back" size={22} color="#FFFFFF" />
            </TouchableOpacity>
          </View>

          <View style={styles.heroCard}>
            <View style={styles.heroIcon}>
              <MaterialIcons name="queue-music" size={26} color="#FFC857" />
            </View>

            <View style={styles.heroTextContainer}>
              <Text style={styles.heroTitle}>Monte seu repertório</Text>
              <Text style={styles.heroDescription}>
                Organize as músicas, tons e links para o dia do culto.
              </Text>
            </View>
          </View>

          <View style={styles.formCard}>
            <View style={styles.sectionHeader}>
              <View style={styles.sectionIcon}>
                <MaterialIcons name="event-note" size={19} color="#40E0D0" />
              </View>
              <View>
                <Text style={styles.sectionEyebrow}>INFORMAÇÕES</Text>
                <Text style={styles.sectionTitle}>Dados do repertório</Text>
              </View>
            </View>

            <Text style={styles.fieldLabel}>Título do repertório</Text>
            <View style={styles.inputWrapper}>
              <MaterialIcons name="title" size={20} color="#7E8DAA" />
              <TextInput
                style={styles.input}
                value={titulo}
                onChangeText={setTitulo}
                placeholder="Ex.: Culto de Domingo"
                placeholderTextColor="#6F7B95"
              />
            </View>

            <View style={[styles.twoColumns, layoutMobile && styles.twoColumnsMobile]}>
              <View style={layoutMobile ? styles.columnMobile : styles.columnLeft}>
                <Text style={styles.fieldLabel}>Data</Text>
                <TouchableOpacity
                  style={styles.inputWrapper}
                  onPress={abrirCalendario}
                  activeOpacity={0.8}
                >
                  <MaterialIcons
                    name="calendar-today"
                    size={18}
                    color="#7E8DAA"
                  />
                  <Text style={[styles.dateText, !data && styles.datePlaceholder]}>
                    {data || 'Escolher'}
                  </Text>
                  <MaterialIcons name="keyboard-arrow-down" size={20} color="#40E0D0" />
                </TouchableOpacity>
              </View>

              <View style={layoutMobile ? styles.columnMobile : styles.columnRight}>
                <Text style={styles.fieldLabel}>Responsável</Text>
                <View style={styles.inputWrapper}>
                  <MaterialIcons
                    name="person-outline"
                    size={19}
                    color="#7E8DAA"
                  />
                  <TextInput
                    style={styles.input}
                    value={responsavel}
                    onChangeText={setResponsavel}
                    placeholder="Nome"
                    placeholderTextColor="#6F7B95"
                  />
                </View>
              </View>
            </View>
          </View>

          <View style={styles.formCard}>
            <View style={styles.sectionHeader}>
              <View style={[styles.sectionIcon, styles.sectionIconPink]}>
                <MaterialIcons name="library-music" size={19} color="#FF4D73" />
              </View>
              <View style={styles.sectionTitleArea}>
                <Text style={styles.sectionEyebrow}>MÚSICAS</Text>
                <Text style={styles.sectionTitle}>Adicionar música</Text>
              </View>
              <View style={styles.musicCount}>
                <Text style={styles.musicCountNumber}>{musicas.length}</Text>
                <Text style={styles.musicCountText}>
                  {musicas.length === 1 ? 'MÚSICA' : 'MÚSICAS'}
                </Text>
              </View>
            </View>

            <Text style={styles.fieldLabel}>Nome da música</Text>
            <View style={styles.autocompleteContainer}>
              <View style={styles.inputWrapper}>
                <MaterialIcons name="music-note" size={20} color="#7E8DAA" />
                <TextInput
                  style={styles.input}
                  value={musicaNome}
                  onChangeText={texto => {
                    setMusicaNome(texto);
                    setMostrarSugestoes(true);
                  }}
                  onFocus={() => setMostrarSugestoes(true)}
                  placeholder="Digite ou selecione uma música"
                  placeholderTextColor="#6F7B95"
                />
                {carregandoCatalogo && <ActivityIndicator size="small" color="#40E0D0" />}
              </View>

              {mostrarSugestoes && sugestoesMusicas.length > 0 && (
                <View style={styles.suggestionsBox}>
                  {sugestoesMusicas.map((musica, indice) => (
                    <TouchableOpacity
                      key={musica.id}
                      style={[
                        styles.suggestionItem,
                        indice === sugestoesMusicas.length - 1 && styles.suggestionItemLast,
                      ]}
                      onPress={() => selecionarMusicaDoBanco(musica)}
                      activeOpacity={0.75}
                    >
                      <View style={styles.suggestionIcon}>
                        <MaterialIcons name="library-music" size={17} color="#40E0D0" />
                      </View>
                      <Text style={styles.suggestionName} numberOfLines={1}>{musica.nome}</Text>
                      <View style={styles.suggestionTone}>
                        <Text style={styles.suggestionToneText}>{musica.tom || 'C'}</Text>
                      </View>
                    </TouchableOpacity>
                  ))}
                </View>
              )}

              {mostrarSugestoes
                && !carregandoCatalogo
                && musicaNome.trim().length > 0
                && sugestoesMusicas.length === 0 && (
                  <View style={styles.noSuggestionBox}>
                    <MaterialIcons name="search-off" size={18} color="#7787A4" />
                    <View style={styles.noSuggestionTextArea}>
                      <Text style={styles.noSuggestionTitle}>Música não encontrada</Text>
                      <Text style={styles.noSuggestionText}>Você pode continuar digitando e cadastrar uma nova.</Text>
                    </View>
                  </View>
                )}
            </View>

            <Text style={styles.fieldLabel}>Tom da música</Text>
            <View style={styles.tonesContainer}>
              <Text style={styles.toneGroupTitle}>MAIORES</Text>
              <View style={styles.toneButtons}>
                {tonsMaiores.map(tom => (
                  <TouchableOpacity
                    key={tom}
                    style={[
                      styles.toneButton,
                      musicaTom === tom && styles.toneButtonActive,
                    ]}
                    onPress={() => setMusicaTom(tom)}
                    activeOpacity={0.8}
                  >
                    <Text
                      style={[
                        styles.toneButtonText,
                        musicaTom === tom && styles.toneButtonTextActive,
                      ]}
                    >
                      {tom}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>

              <Text style={[styles.toneGroupTitle, styles.minorToneTitle]}>
                MENORES
              </Text>
              <View style={styles.toneButtons}>
                {tonsMenores.map(tom => (
                  <TouchableOpacity
                    key={tom}
                    style={[
                      styles.toneButton,
                      musicaTom === tom && styles.toneButtonActive,
                    ]}
                    onPress={() => setMusicaTom(tom)}
                    activeOpacity={0.8}
                  >
                    <Text
                      style={[
                        styles.toneButtonText,
                        musicaTom === tom && styles.toneButtonTextActive,
                      ]}
                    >
                      {tom}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>

            <Text style={styles.fieldLabel}>Link da letra <Text style={styles.optional}>(opcional)</Text></Text>
            <View style={styles.inputWrapper}>
              <MaterialIcons name="description" size={19} color="#7E8DAA" />
              <TextInput
                style={styles.input}
                value={musicaLinkLetra}
                onChangeText={setMusicaLinkLetra}
                placeholder="https://..."
                placeholderTextColor="#6F7B95"
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="url"
              />
            </View>

            <Text style={styles.fieldLabel}>Link do YouTube <Text style={styles.optional}>(opcional)</Text></Text>
            <View style={styles.inputWrapper}>
              <MaterialIcons name="play-circle-outline" size={20} color="#7E8DAA" />
              <TextInput
                style={styles.input}
                value={musicaLinkYoutube}
                onChangeText={setMusicaLinkYoutube}
                placeholder="https://youtube.com/..."
                placeholderTextColor="#6F7B95"
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="url"
              />
            </View>

            <Text style={styles.fieldLabel}>Link da cifra <Text style={styles.optional}>(opcional)</Text></Text>
            <View style={styles.inputWrapper}>
              <MaterialIcons name="queue-music" size={20} color="#7E8DAA" />
              <TextInput
                style={styles.input}
                value={musicaLinkCifra}
                onChangeText={setMusicaLinkCifra}
                placeholder="https://cifraclub.com.br/..."
                placeholderTextColor="#6F7B95"
                autoCapitalize="none"
                autoCorrect={false}
                keyboardType="url"
              />
            </View>

            <Text style={styles.fieldLabel}>Observações <Text style={styles.optional}>(opcional)</Text></Text>
            <View style={[styles.inputWrapper, styles.textAreaWrapper]}>
              <MaterialIcons name="notes" size={20} color="#7E8DAA" style={styles.textAreaIcon} />
              <TextInput
                style={[styles.input, styles.textAreaInput]}
                value={musicaObservacoes}
                onChangeText={setMusicaObservacoes}
                placeholder="Ex.: começar no refrão, baixar o tom..."
                placeholderTextColor="#6F7B95"
                multiline
                numberOfLines={3}
                textAlignVertical="top"
              />
            </View>

            <TouchableOpacity
              style={styles.addMusicButton}
              onPress={handleAdicionarMusica}
              activeOpacity={0.85}
            >
              <MaterialIcons name="add-circle-outline" size={21} color="#081224" />
              <Text style={styles.addMusicButtonText}>Adicionar à lista</Text>
            </TouchableOpacity>
          </View>

          {musicas.length > 0 && (
            <View style={styles.listContainer}>
              <View style={styles.listHeader}>
                <View>
                  <Text style={styles.sectionEyebrow}>ORDEM DO REPERTÓRIO</Text>
                  <Text style={styles.listTitle}>Músicas adicionadas</Text>
                </View>
                <Text style={styles.listHint}>Arraste mentalmente 😉</Text>
              </View>

              {musicas.map((musica, index) => (
                <View key={`${musica.nome}-${index}`} style={styles.musicCard}>
                  <View style={styles.musicCardTop}>
                    <View style={styles.numberCircle}>
                      <Text style={styles.numberText}>{index + 1}</Text>
                    </View>

                    <View style={styles.songInfo}>
                      <Text style={styles.songType}>MÚSICA</Text>
                      <Text style={styles.songName} numberOfLines={2}>
                        {musica.nome}
                      </Text>
                    </View>

                    {renderTom(musica.tom)}
                  </View>

                  <View style={styles.musicCardActions}>
                    <TouchableOpacity
                      style={[
                        styles.resourceButton,
                        styles.lyricsButton,
                        !musica.linkLetra && styles.disabledButton,
                      ]}
                      onPress={() => abrirLink(musica.linkLetra, 'letra')}
                      activeOpacity={0.8}
                    >
                      <MaterialIcons
                        name="description"
                        size={17}
                        color={
                          musica.linkLetra ? '#C8D2E8' : '#61708C'
                        }
                      />
                      <Text
                        style={[
                          styles.resourceButtonText,
                          !musica.linkLetra && styles.disabledButtonText,
                        ]}
                      >
                        Letra
                      </Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={[
                        styles.resourceButton,
                        styles.youtubeButton,
                        !musica.linkYoutube && styles.disabledYoutubeButton,
                      ]}
                      onPress={() => abrirLink(musica.linkYoutube, 'YouTube')}
                      activeOpacity={0.8}
                    >
                      <MaterialIcons
                        name="play-arrow"
                        size={19}
                        color={
                          musica.linkYoutube ? '#FFFFFF' : '#61708C'
                        }
                      />
                      <Text
                        style={[
                          styles.resourceButtonText,
                          styles.youtubeButtonText,
                          !musica.linkYoutube && styles.disabledButtonText,
                        ]}
                      >
                        YouTube
                      </Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={[
                        styles.resourceButton,
                        styles.cifraButton,
                        !musica.linkCifra && styles.disabledButton,
                      ]}
                      onPress={() => abrirLink(musica.linkCifra, 'cifra')}
                      activeOpacity={0.8}
                    >
                      <MaterialIcons
                        name="queue-music"
                        size={18}
                        color={musica.linkCifra ? '#081224' : '#61708C'}
                      />
                      <Text
                        style={[
                          styles.resourceButtonText,
                          styles.cifraButtonText,
                          !musica.linkCifra && styles.disabledButtonText,
                        ]}
                      >
                        Cifra
                      </Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={styles.deleteButton}
                      onPress={() => removerMusica(index)}
                      activeOpacity={0.8}
                    >
                      <MaterialIcons
                        name="delete-outline"
                        size={21}
                        color="#FF718C"
                      />
                    </TouchableOpacity>
                  </View>

                  {!!musica.observacoes && (
                    <View style={styles.musicObservation}>
                      <MaterialIcons name="notes" size={15} color="#8FA2C3" />
                      <Text style={styles.musicObservationText}>{musica.observacoes}</Text>
                    </View>
                  )}
                </View>
              ))}
            </View>
          )}

          <Animated.View
            style={[
              styles.saveButtonContainer,
              { transform: [{ scale: saveAnim }] },
            ]}
          >
            <TouchableOpacity
              style={[
                styles.saveButton,
                loading && styles.saveButtonLoading,
              ]}
              onPress={salvarRepertorio}
              disabled={loading}
              onPressIn={handlePressIn}
              onPressOut={handlePressOut}
              activeOpacity={0.9}
            >
              {loading ? (
                <ActivityIndicator color="#081224" />
              ) : (
                <>
                  <MaterialIcons name="save-alt" size={22} color="#081224" />
                  <Text style={styles.saveButtonText}>Salvar repertório</Text>
                </>
              )}
            </TouchableOpacity>
          </Animated.View>

          <TouchableOpacity
            style={styles.cancelButton}
            onPress={() => navigation.goBack()}
            activeOpacity={0.8}
          >
            <Text style={styles.cancelButtonText}>Cancelar e voltar</Text>
          </TouchableOpacity>
        </ScrollView>
      </KeyboardAvoidingView>

      <Modal
        visible={calendarioVisivel}
        transparent
        animationType="fade"
        onRequestClose={() => setCalendarioVisivel(false)}
      >
        <View style={styles.calendarOverlay}>
          <View style={styles.calendarCard}>
            <View style={styles.calendarHeader}>
              <TouchableOpacity style={styles.calendarNavButton} onPress={() => mudarMes(-1)}>
                <MaterialIcons name="chevron-left" size={27} color="#DDE7FA" />
              </TouchableOpacity>
              <View style={styles.calendarTitleArea}>
                <Text style={styles.calendarEyebrow}>ESCOLHA A DATA</Text>
                <Text style={styles.calendarTitle}>
                  {MESES[mesCalendario.getMonth()]} {mesCalendario.getFullYear()}
                </Text>
              </View>
              <TouchableOpacity style={styles.calendarNavButton} onPress={() => mudarMes(1)}>
                <MaterialIcons name="chevron-right" size={27} color="#DDE7FA" />
              </TouchableOpacity>
            </View>

            <View style={styles.weekRow}>
              {DIAS_SEMANA.map((dia, indice) => (
                <Text key={`${dia}-${indice}`} style={styles.weekDay}>{dia}</Text>
              ))}
            </View>

            <View style={styles.calendarGrid}>
              {diasDoCalendario.map((dia, indice) => {
                const selecionado = dia !== null && diaEstaSelecionado(dia);
                const hoje = dia !== null && diaEhHoje(dia);
                return (
                  <View key={`${dia || 'vazio'}-${indice}`} style={styles.dayCell}>
                    {dia !== null && (
                      <TouchableOpacity
                        style={[
                          styles.dayButton,
                          hoje && styles.todayButton,
                          selecionado && styles.selectedDayButton,
                        ]}
                        onPress={() => selecionarDia(dia)}
                        activeOpacity={0.75}
                      >
                        <Text
                          style={[
                            styles.dayText,
                            hoje && styles.todayText,
                            selecionado && styles.selectedDayText,
                          ]}
                        >
                          {dia}
                        </Text>
                      </TouchableOpacity>
                    )}
                  </View>
                );
              })}
            </View>

            <View style={styles.calendarActions}>
              <TouchableOpacity
                style={styles.calendarCancelButton}
                onPress={() => setCalendarioVisivel(false)}
              >
                <Text style={styles.calendarCancelText}>Cancelar</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={styles.calendarTodayAction}
                onPress={() => {
                  const hoje = new Date();
                  setMesCalendario(hoje);
                  setData(formatarData(hoje));
                  setCalendarioVisivel(false);
                }}
              >
                <MaterialIcons name="today" size={17} color="#081224" />
                <Text style={styles.calendarTodayText}>Hoje</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
}

