function getHoje() {
  const hoje = new Date();
  const dia = String(hoje.getDate()).padStart(2, '0');
  const mes = String(hoje.getMonth() + 1).padStart(2, '0');
  const ano = hoje.getFullYear();
  // padrao dd/mm/yyyy
  return `${dia}/${mes}/${ano}`;
}

// Função para comparar datas
function compararComDataAtual(dataInput: string): 'anterior' | 'hoje' | 'posterior' {
  if (!dataInput || dataInput.length < 10) return 'hoje';
  try {
    // aceita dd/mm/aaaa ou dd-mm-aaaa
    const dataFormatada = dataInput.replace(/\//g, '-');
    const [dia, mes, ano] = dataFormatada.split('-').map(Number);
    if (!dia || !mes || !ano) return 'hoje';
    const dataUsuario = new Date(ano, mes - 1, dia);
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    dataUsuario.setHours(0, 0, 0, 0);
    if (dataUsuario < hoje) return 'anterior';
    if (dataUsuario > hoje) return 'posterior';
    return 'hoje';
  } catch {
    return 'hoje';
  }
}

async function salvarPresencasNoBanco(presencas: any, fotosUsuarios?: any) {
  try {
    const presencaSnap = await getDocs(collection(db, 'presencas'));
    const presencasBanco = presencaSnap.docs.reduce((acc, docSnap) => ({
      ...acc,
      ...(docSnap.data().presencas || {}),
    }), {});
    await setDoc(doc(db, 'presencas', 'atual'), {
      presencas: { ...presencasBanco, ...presencas },
    }, { merge: true });
  } catch (error) {
    Alert.alert('Erro', 'Não foi possível salvar as presenças.');
  }
}

async function salvarFotoUsuarioNoBanco(uid: string, foto: string) {
  await setDoc(doc(db, 'presencas', 'atual'), {
    fotosPorUid: {
      [uid]: foto,
    },
  }, { merge: true });
}

function fotosPorUidParaNomes(fotosPorUid: Record<string, unknown>) {
  return Object.entries(fotosPorUid).reduce((acc, [uid, foto]) => {
    const nome = UID_TO_NOME[uid];
    if (nome && typeof foto === 'string') {
      acc[nome] = foto;
    }
    return acc;
  }, {} as Record<string, string>);
}

function montarCropQuadrado(width?: number, height?: number) {
  if (!width || !height) return null;

  const tamanho = Math.min(width, height);
  return {
    originX: Math.max(0, Math.floor((width - tamanho) / 2)),
    originY: Math.max(0, Math.floor((height - tamanho) / 2)),
    width: tamanho,
    height: tamanho,
  };
}

function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

function dataParaDate(data?: string) {
  if (!data || data.length < 10) return new Date();
  const [dia, mes, ano] = data.split(/[/-]/).map(Number);
  if (!dia || !mes || !ano) return new Date();
  return new Date(ano, mes - 1, dia);
}

function dateParaData(data: Date) {
  const dia = String(data.getDate()).padStart(2, '0');
  const mes = String(data.getMonth() + 1).padStart(2, '0');
  const ano = data.getFullYear();
  return `${dia}/${mes}/${ano}`;
}

