    if (!uidAtual || nomeUsuarioAtual !== nome) return;
    const dataBase = idx === null ? new Date() : dataParaDate(presencas[nome]?.datas?.[idx]);
    setMesCalendario(new Date(dataBase.getFullYear(), dataBase.getMonth(), 1));
    setCalendario({ nome, idx });
